// 1. Funciones de Inicialización y Cierre (¡Ambas declaradas!)

def __new__(cls):
    if cls._instance is None:
        cls._instance = super().__new__(cls)
        cls._instance._initialized = False
    return cls._instance

def __init__(self):
    if self._initialized:
        return

    if not HID_AVAILABLE:
        raise RuntimeError("hidapi no está disponible")

    is_valid, message = validate_configuration()
    if not is_valid:
        raise RuntimeError(f"Configuración inválida: {message}")

    self._handle: Optional[hid.device] = None
    self._initialized = True

def close(self):
    """Cierra la conexión con el dispositivo."""
    if self._handle:
        try:
            self._handle.close()
            print("✅ Dispositivo VSL cerrado")
        except Exception as e:
            print(f"⚠️ Error cerrando dispositivo: {e}")
        finally:
            self._handle = None

def __exit__(self, exc_type, exc_val, exc_tb):
    """Context manager exit."""
    self.close()

def buffer(self) -> bytes:
    """Retorna el buffer como bytes inmutables."""
    return bytes(self._buffer)

def __repr__(self) -> str:
    return (
        f"VSLPacket(report_id=0x{self.report_id:02X}, "
        f"param_id=0x{self.param_id:04X}, "
        f"value={self.encoded_value})"
    )

