        case VC_EFFECT_METALLIC:
            return ring_valid(p, nyquist) &&
                   p->delay_ms > 0.0f &&
                   p->delay_ms <= VC_METALLIC_MAX_DELAY_MS &&
                   p->feedback >= 0.0f &&
