        long t = (long)floor((double)c->peaks[r] * factor + 0.5);
        c->delta[r] = (ptrdiff_t)(t - (long)c->peaks[r]);
    }
    for (b = 0; b < nbins; ++b) {
        dst_mag[b] = 0.0f;
        dst_hz[b] = (double)b * freq_per_bin;
