int vc_rt_derive(const unsigned char *pitch_seed,
                 const unsigned char *formant_seed,
                 const unsigned char *spectral_seed,
                 int witness_mode, vc_rt_params_t *out) {
    if (!pitch_seed || !formant_seed || !spectral_seed || !out) return -1;

    vc_prng_t *pp = vc_prng_create(pitch_seed);
    vc_prng_t *pf = vc_prng_create(formant_seed);
    vc_prng_t *ps = vc_prng_create(spectral_seed);
    if (!pp || !pf || !ps) {
        vc_prng_destroy(pp); vc_prng_destroy(pf); vc_prng_destroy(ps);
        return -1;
    }

    float pitch_semitones, formant_factor, scramble_intensity;
    if (witness_mode) {
        pitch_semitones    = vc_prng_float(pp, -10.0f, 10.0f);
        formant_factor     = vc_prng_float(pf, 0.5f, 1.8f);
        scramble_intensity = vc_prng_float(ps, 0.6f, 1.0f);
    } else {
        pitch_semitones    = vc_prng_float(pp, -3.0f, 3.0f);
        formant_factor     = vc_prng_float(pf, 0.85f, 1.15f);
        scramble_intensity = vc_prng_float(ps, 0.1f, 0.3f);
    }

    vc_prng_destroy(pp);
    vc_prng_destroy(pf);
    vc_prng_destroy(ps);

    out->pitch_ratio        = vc_rt_semitones_to_ratio(pitch_semitones);
    out->formant_factor     = formant_factor;
    out->scramble_intensity = scramble_intensity;
    out->robotize           = 0;
    return 0;
}

struct vc_stft_s {
    size_t fft_size;
    size_t hop_size;
    size_t nbins;
    float *window;
    float *win_sq_sum;
    float *buf_r;
    float *buf_i;
};

vc_stft_t *vc_stft_create(size_t fft_size, size_t hop_size) {
    vc_stft_t *st = (vc_stft_t *)malloc(sizeof(vc_stft_t));
    if (!st) return NULL;

    st->fft_size = fft_size;
    st->hop_size = hop_size;
    st->nbins    = fft_size / 2 + 1;

    st->window   = (float *)malloc(fft_size * sizeof(float));
    st->win_sq_sum = (float *)malloc(fft_size * sizeof(float));
    st->buf_r    = (float *)malloc(fft_size * sizeof(float));
    st->buf_i    = (float *)malloc(fft_size * sizeof(float));

    if (!st->window || !st->win_sq_sum || !st->buf_r || !st->buf_i) {
        vc_stft_destroy(st);
        return NULL;
    }

    size_t i;
    for (i = 0; i < fft_size; ++i) {
        st->window[i] = 0.5f * (1.0f - cosf(2.0f * (float)M_PI * (float)i / (float)(fft_size - 1)));
    }

    /* Compute overlap-add normalization for synthesis hop */
    memset(st->win_sq_sum, 0, fft_size * sizeof(float));
    /* Pre-compute for default analysis hop (caller can override for synthesis) */
    size_t pos;
    for (pos = 0; pos < fft_size; pos += hop_size) {
        for (i = 0; i < fft_size && (pos + i) < fft_size + fft_size; ++i) {
            float w = st->window[i];
            st->win_sq_sum[(pos + i) % fft_size] += w * w;
        }
    }

    return st;
}

void vc_stft_destroy(vc_stft_t *st) {
    if (!st) return;
    free(st->window);
    free(st->win_sq_sum);
    free(st->buf_r);
    free(st->buf_i);
    free(st);
}

size_t vc_stft_num_bins(const vc_stft_t *st) {
