        float *m = mag_out   + f * nbins;
        float *p = phase_out + f * nbins;
        for (b = 0; b < nbins; ++b) {
            m[b] = sqrtf(st->buf_r[b] * st->buf_r[b] + st->buf_i[b] * st->buf_i[b]);
            p[b] = atan2f(st->buf_i[b], st->buf_r[b]);
